    AccessKey.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: StatusType, location_name: 'status', traits: {"smithy.api#documentation" => "<p>The status of the access key.</p>\n         <p>A status of <code>Active</code> means that the key is valid, while <code>Inactive</code>\n      means it is not.</p>"}))
    AccessKey.add_member(:created_at, Smithy::Schema::Shapes::ShapeRef.new(shape: IsoDate, location_name: 'createdAt', traits: {"smithy.api#documentation" => "<p>The timestamp when the access key was created.</p>"}))
    AccessKey.add_member(:last_used, Smithy::Schema::Shapes::ShapeRef.new(shape: AccessKeyLastUsed, location_name: 'lastUsed', traits: {"smithy.api#documentation" => "<p>An object that describes the last time the access key was used.</p>\n         <note>\n            <p>This object does not include data in the response of a <a href=\"https://docs.aws.amazon.com/lightsail/2016-11-28/api-reference/API_CreateBucketAccessKey.html\">CreateBucketAccessKey</a> action. If the access key has not been used, the\n          <code>region</code> and <code>serviceName</code> values are <code>N/A</code>, and the\n          <code>lastUsedDate</code> value is null.</p>\n         </note>"}))
