    AddOn.add_member(:threshold, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'threshold', traits: {"smithy.api#documentation" => "<p>The trigger threshold of the action.</p>\n         <important>\n            <p>This add-on only applies to Lightsail for Research resources.</p>\n         </important>"}))
