    Alarm.add_member(:created_at, Smithy::Schema::Shapes::ShapeRef.new(shape: IsoDate, location_name: 'createdAt', traits: {"smithy.api#documentation" => "<p>The timestamp when the alarm was created.</p>"}))
    Alarm.add_member(:location, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceLocation, location_name: 'location', traits: {"smithy.api#documentation" => "<p>An object that lists information about the location of the alarm.</p>"}))
    Alarm.add_member(:resource_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceType, location_name: 'resourceType', traits: {"smithy.api#documentation" => "<p>The Lightsail resource type of the alarm.</p>"}))
    Alarm.add_member(:support_code, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'supportCode', traits: {"smithy.api#documentation" => "<p>The support code. Include this code in your email to support when you have questions about\n      your Lightsail alarm. This code enables our support team to look up your Lightsail\n      information more easily.</p>"}))
    Alarm.add_member(:monitored_resource_info, Smithy::Schema::Shapes::ShapeRef.new(shape: MonitoredResourceInfo, location_name: 'monitoredResourceInfo', traits: {"smithy.api#documentation" => "<p>An object that lists information about the resource monitored by the alarm.</p>"}))
    Alarm.add_member(:comparison_operator, Smithy::Schema::Shapes::ShapeRef.new(shape: ComparisonOperator, location_name: 'comparisonOperator', traits: {"smithy.api#documentation" => "<p>The arithmetic operation used when comparing the specified statistic and threshold.</p>"}))
    Alarm.add_member(:evaluation_periods, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'evaluationPeriods', traits: {"smithy.api#documentation" => "<p>The number of periods over which data is compared to the specified threshold.</p>"}))
    Alarm.add_member(:period, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricPeriod, location_name: 'period', traits: {"smithy.api#documentation" => "<p>The period, in seconds, over which the statistic is applied.</p>"}))
    Alarm.add_member(:threshold, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'threshold', traits: {"smithy.api#documentation" => "<p>The value against which the specified statistic is compared.</p>"}))
    Alarm.add_member(:datapoints_to_alarm, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'datapointsToAlarm', traits: {"smithy.api#documentation" => "<p>The number of data points that must not within the specified threshold to trigger the\n      alarm.</p>"}))
    Alarm.add_member(:treat_missing_data, Smithy::Schema::Shapes::ShapeRef.new(shape: TreatMissingData, location_name: 'treatMissingData', traits: {"smithy.api#documentation" => "<p>Specifies how the alarm handles missing data points.</p>\n         <p>An alarm can treat missing data in the following ways:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>breaching</code> - Assume the missing data is not within the threshold. Missing\n          data counts towards the number of times the metric is not within the threshold.</p>\n            </li>\n            <li>\n               <p>\n                  <code>notBreaching</code> - Assume the missing data is within the threshold. Missing\n          data does not count towards the number of times the metric is not within the\n          threshold.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ignore</code> - Ignore the missing data. Maintains the current alarm\n          state.</p>\n            </li>\n            <li>\n               <p>\n                  <code>missing</code> - Missing data is treated as missing.</p>\n            </li>\n         </ul>"}))
    Alarm.add_member(:statistic, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricStatistic, location_name: 'statistic', traits: {"smithy.api#documentation" => "<p>The statistic for the metric associated with the alarm.</p>\n         <p>The following statistics are available:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>Minimum</code> - The lowest value observed during the specified period. Use this\n          value to determine low volumes of activity for your application.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Maximum</code> - The highest value observed during the specified period. Use\n          this value to determine high volumes of activity for your application.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Sum</code> - All values submitted for the matching metric added together. You\n          can use this statistic to determine the total volume of a metric.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Average</code> - The value of Sum / SampleCount during the specified period. By\n          comparing this statistic with the Minimum and Maximum values, you can determine the full\n          scope of a metric and how close the average use is to the Minimum and Maximum values. This\n          comparison helps you to know when to increase or decrease your resources.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SampleCount</code> - The count, or number, of data points used for the\n          statistical calculation.</p>\n            </li>\n         </ul>"}))
    Alarm.add_member(:metric_name, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricName, location_name: 'metricName', traits: {"smithy.api#documentation" => "<p>The name of the metric associated with the alarm.</p>"}))
    Alarm.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: AlarmState, location_name: 'state', traits: {"smithy.api#documentation" => "<p>The current state of the alarm.</p>\n         <p>An alarm has the following possible states:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ALARM</code> - The metric is outside of the defined threshold.</p>\n            </li>\n            <li>\n               <p>\n                  <code>INSUFFICIENT_DATA</code> - The alarm has just started, the metric is not\n          available, or not enough data is available for the metric to determine the alarm\n          state.</p>\n            </li>\n            <li>\n               <p>\n                  <code>OK</code> - The metric is within the defined threshold.</p>\n            </li>\n         </ul>"}))
    Alarm.add_member(:unit, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricUnit, location_name: 'unit', traits: {"smithy.api#documentation" => "<p>The unit of the metric associated with the alarm.</p>"}))
