    Bundle.add_member(:power, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'power', traits: {"smithy.api#documentation" => "<p>A numeric value that represents the power of the bundle (<code>500</code>). You can use\n      the bundle's power value in conjunction with a blueprint's minimum power value to determine\n      whether the blueprint will run on the bundle. For example, you need a bundle with a power\n      value of 500 or more to create an instance that uses a blueprint with a minimum power value of\n      500.</p>"}))
    Bundle.add_member(:ram_size_in_gb, Smithy::Schema::Shapes::ShapeRef.new(shape: Float, location_name: 'ramSizeInGb', traits: {"smithy.api#documentation" => "<p>The amount of RAM in GB (<code>2.0</code>).</p>"}))
    Bundle.add_member(:transfer_per_month_in_gb, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'transferPerMonthInGb', traits: {"smithy.api#documentation" => "<p>The data transfer rate per month in GB (<code>2000</code>).</p>"}))
    Bundle.add_member(:supported_platforms, Smithy::Schema::Shapes::ShapeRef.new(shape: InstancePlatformList, location_name: 'supportedPlatforms', traits: {"smithy.api#documentation" => "<p>The operating system platform (Linux/Unix-based or Windows Server-based) that the bundle\n      supports. You can only launch a <code>WINDOWS</code> bundle on a blueprint that supports the\n        <code>WINDOWS</code> platform. <code>LINUX_UNIX</code> blueprints require a\n        <code>LINUX_UNIX</code> bundle.</p>"}))
    Bundle.add_member(:supported_app_categories, Smithy::Schema::Shapes::ShapeRef.new(shape: AppCategoryList, location_name: 'supportedAppCategories', traits: {"smithy.api#documentation" => "<p>Virtual computer blueprints that are supported by a Lightsail for Research bundle.</p>\n         <important>\n            <p>This parameter only applies to Lightsail for Research resources.</p>\n         </important>"}))
