    ContainerService.add_member(:power, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerServicePowerName, location_name: 'power', traits: {"smithy.api#documentation" => "<p>The power specification of the container service.</p>\n         <p>The power specifies the amount of RAM, the number of vCPUs, and the base price of the\n      container service.</p>"}))
    ContainerService.add_member(:power_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'powerId', traits: {"smithy.api#documentation" => "<p>The ID of the power of the container service.</p>"}))
    ContainerService.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerServiceState, location_name: 'state', traits: {"smithy.api#documentation" => "<p>The current state of the container service.</p>\n         <p>The following container service states are possible:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>PENDING</code> - The container service is being created.</p>\n            </li>\n            <li>\n               <p>\n                  <code>READY</code> - The container service is running but it does not have an active\n          container deployment.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DEPLOYING</code> - The container service is launching a container\n          deployment.</p>\n            </li>\n            <li>\n               <p>\n                  <code>RUNNING</code> - The container service is running and it has an active container\n          deployment.</p>\n            </li>\n            <li>\n               <p>\n                  <code>UPDATING</code> - The container service capacity or its custom domains are being\n          updated.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETING</code> - The container service is being deleted.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DISABLED</code> - The container service is disabled, and its active deployment\n          and containers, if any, are shut down.</p>\n            </li>\n         </ul>"}))
    ContainerService.add_member(:state_detail, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerServiceStateDetail, location_name: 'stateDetail', traits: {"smithy.api#documentation" => "<p>An object that describes the current state of the container service.</p>\n         <note>\n            <p>The state detail is populated only when a container service is in a\n        <code>PENDING</code>, <code>DEPLOYING</code>, or <code>UPDATING</code> state.</p>\n         </note>"}))
    ContainerService.add_member(:scale, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerServiceScale, location_name: 'scale', traits: {"smithy.api#documentation" => "<p>The scale specification of the container service.</p>\n         <p>The scale specifies the allocated compute nodes of the container service.</p>"}))
    ContainerService.add_member(:current_deployment, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerServiceDeployment, location_name: 'currentDeployment', traits: {"smithy.api#documentation" => "<p>An object that describes the current container deployment of the container service.</p>"}))
    ContainerService.add_member(:next_deployment, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerServiceDeployment, location_name: 'nextDeployment', traits: {"smithy.api#documentation" => "<p>An object that describes the next deployment of the container service.</p>\n         <p>This value is <code>null</code> when there is no deployment in a <code>pending</code>\n      state.</p>"}))
    ContainerService.add_member(:is_disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'isDisabled', traits: {"smithy.api#documentation" => "<p>A Boolean value indicating whether the container service is disabled.</p>"}))
    ContainerService.add_member(:principal_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'principalArn', traits: {"smithy.api#documentation" => "<p>The principal ARN of the container service.</p>\n         <p>The principal ARN can be used to create a trust relationship between your standard Amazon Web Services account and your Lightsail container service. This allows you to give your\n      service permission to access resources in your standard Amazon Web Services account.</p>"}))
    ContainerService.add_member(:private_domain_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'privateDomainName', traits: {"smithy.api#documentation" => "<p>The private domain name of the container service.</p>\n         <p>The private domain name is accessible only by other resources within the default virtual\n      private cloud (VPC) of your Lightsail account.</p>"}))
    ContainerService.add_member(:public_domain_names, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerServicePublicDomains, location_name: 'publicDomainNames', traits: {"smithy.api#documentation" => "<p>The public domain name of the container service, such as <code>example.com</code> and\n        <code>www.example.com</code>.</p>\n         <p>You can specify up to four public domain names for a container service. The domain names\n      that you specify are used when you create a deployment with a container configured as the\n      public endpoint of your container service.</p>\n         <p>If you don't specify public domain names, then you can use the default domain of the\n      container service.</p>\n         <important>\n            <p>You must create and validate an SSL/TLS certificate before you can use public domain\n        names with your container service. Use the <code>CreateCertificate</code> action to create a\n        certificate for the public domain names you want to use with your container service.</p>\n         </important>\n         <p>See <code>CreateContainerService</code> or <code>UpdateContainerService</code> for\n      information about how to specify public domain names for your Lightsail container\n      service.</p>"}))
    ContainerService.add_member(:url, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'url', traits: {"smithy.api#documentation" => "<p>The publicly accessible URL of the container service.</p>\n         <p>If no public endpoint is specified in the <code>currentDeployment</code>, this URL returns\n      a 404 response.</p>"}))
    ContainerService.add_member(:private_registry_access, Smithy::Schema::Shapes::ShapeRef.new(shape: PrivateRegistryAccess, location_name: 'privateRegistryAccess', traits: {"smithy.api#documentation" => "<p>An object that describes the configuration for the container service to access private\n      container image repositories, such as Amazon Elastic Container Registry (Amazon ECR) private\n      repositories.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/lightsail/latest/userguide/amazon-lightsail-container-service-ecr-private-repo-access\">Configuring access to an Amazon ECR private repository for an Amazon Lightsail container service</a> in the <i>Amazon Lightsail Developer Guide</i>.</p>"}))
    ContainerService.type = Types::ContainerService
    ContainerServiceDeployment.add_member(:version, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'version', traits: {"smithy.api#documentation" => "<p>The version number of the deployment.</p>"}))
    ContainerServiceDeployment.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerServiceDeploymentState, location_name: 'state', traits: {"smithy.api#documentation" => "<p>The state of the deployment.</p>\n         <p>A deployment can be in one of the following states:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ACTIVATING</code> - The deployment is being created.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ACTIVE</code> - The deployment was successfully created, and it's currently\n          running on the container service. The container service can have only one deployment in an\n          active state at a time.</p>\n            </li>\n            <li>\n               <p>\n                  <code>INACTIVE</code> - The deployment was previously successfully created, but it is\n          not currently running on the container service.</p>\n            </li>\n            <li>\n               <p>\n                  <code>FAILED</code> - The deployment failed. Use the <code>GetContainerLog</code>\n          action to view the log events for the containers in the deployment to try to determine the\n          reason for the failure.</p>\n            </li>\n         </ul>"}))
