    CreateInstancesFromSnapshotRequest.add_member(:ip_address_type, Smithy::Schema::Shapes::ShapeRef.new(shape: IpAddressType, location_name: 'ipAddressType', traits: {"smithy.api#documentation" => "<p>The IP address type for the instance.</p>\n         <p>The possible values are <code>ipv4</code> for IPv4 only, <code>ipv6</code> for IPv6 only,\n      and <code>dualstack</code> for IPv4 and IPv6.</p>\n         <p>The default value is <code>dualstack</code>.</p>"}))
