    CreateRelationalDatabaseFromSnapshotRequest.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'publiclyAccessible', traits: {"smithy.api#documentation" => "<p>Specifies the accessibility options for your new database. A value of <code>true</code>\n      specifies a database that is available to resources outside of your Lightsail account. A\n      value of <code>false</code> specifies a database that is available only to your Lightsail\n      resources in the same region as your database.</p>"}))
