    CreateRelationalDatabaseFromSnapshotRequest.add_member(:restore_time, Smithy::Schema::Shapes::ShapeRef.new(shape: IsoDate, location_name: 'restoreTime', traits: {"smithy.api#documentation" => "<p>The date and time to restore your database from.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be before the latest restorable time for the database.</p>\n            </li>\n            <li>\n               <p>Cannot be specified if the <code>use latest restorable time</code> parameter is\n            <code>true</code>.</p>\n            </li>\n            <li>\n               <p>Specified in Coordinated Universal Time (UTC).</p>\n            </li>\n            <li>\n               <p>Specified in the Unix time format.</p>\n               <p>For example, if you wish to use a restore time of October 1, 2018, at 8 PM UTC, then\n          you input <code>1538424000</code> as the restore time.</p>\n            </li>\n         </ul>"}))
    CreateRelationalDatabaseFromSnapshotRequest.add_member(:use_latest_restorable_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'useLatestRestorableTime', traits: {"smithy.api#documentation" => "<p>Specifies whether your database is restored from the latest backup time. A value of\n        <code>true</code> restores from the latest backup time. </p>\n         <p>Default: <code>false</code>\n         </p>\n         <p>Constraints: Cannot be specified if the <code>restore time</code> parameter is\n      provided.</p>"}))
