    CreateRelationalDatabaseSnapshotRequest.add_member(:relational_database_snapshot_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceName, location_name: 'relationalDatabaseSnapshotName', traits: {"smithy.api#documentation" => "<p>The name for your new database snapshot.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 2 to 255 alphanumeric characters, or hyphens.</p>\n            </li>\n            <li>\n               <p>The first and last character must be a letter or number.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
