    DeleteBucketAccessKeyRequest.add_member(:access_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'accessKeyId', traits: {"smithy.api#documentation" => "<p>The ID of the access key to delete.</p>\n         <p>Use the <a href=\"https://docs.aws.amazon.com/lightsail/2016-11-28/api-reference/API_GetBucketAccessKeys.html\">GetBucketAccessKeys</a> action to get a\n      list of access key IDs that you can specify.</p>", "smithy.api#required" => {}}))
