    DeleteContainerImageRequest.add_member(:service_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerServiceName, location_name: 'serviceName', traits: {"smithy.api#documentation" => "<p>The name of the container service for which to delete a registered container image.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    DeleteContainerImageRequest.add_member(:image, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'image', traits: {"smithy.api#documentation" => "<p>The name of the container image to delete from the container service.</p>\n         <p>Use the <code>GetContainerImages</code> action to get the name of the container images\n      that are registered to a container service.</p>\n         <note>\n            <p>Container images sourced from your Lightsail container service, that are registered\n        and stored on your service, start with a colon (<code>:</code>). For example,\n          <code>:container-service-1.mystaticwebsite.1</code>. Container images sourced from a\n        public registry like Docker Hub don't start with a colon. For example,\n          <code>nginx:latest</code> or <code>nginx</code>.</p>\n         </note>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
