    GetDistributionMetricDataRequest.add_member(:distribution_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceName, location_name: 'distributionName', traits: {"smithy.api#documentation" => "<p>The name of the distribution for which to get metric data.</p>\n         <p>Use the <code>GetDistributions</code> action to get a list of distribution names that you\n      can specify.</p>", "smithy.api#required" => {}}))
    GetDistributionMetricDataRequest.add_member(:metric_name, Smithy::Schema::Shapes::ShapeRef.new(shape: DistributionMetricName, location_name: 'metricName', traits: {"smithy.api#documentation" => "<p>The metric for which you want to return information.</p>\n         <p>Valid distribution metric names are listed below, along with the most useful\n        <code>statistics</code> to include in your request, and the published <code>unit</code>\n      value.</p>\n         <ul>\n            <li>\n               <p>\n                  <b>\n                     <code>Requests</code>\n                  </b> - The total number of viewer\n          requests received by your Lightsail distribution, for all HTTP methods, and for both\n          HTTP and HTTPS requests.</p>\n               <p>\n                  <code>Statistics</code>: The most useful statistic is <code>Sum</code>.</p>\n               <p>\n                  <code>Unit</code>: The published unit is <code>None</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>BytesDownloaded</code>\n                  </b> - The number of bytes\n          downloaded by viewers for GET, HEAD, and OPTIONS requests.</p>\n               <p>\n                  <code>Statistics</code>: The most useful statistic is <code>Sum</code>.</p>\n               <p>\n                  <code>Unit</code>: The published unit is <code>None</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>BytesUploaded </code>\n                  </b> - The number of bytes\n          uploaded to your origin by your Lightsail distribution, using POST and PUT\n          requests.</p>\n               <p>\n                  <code>Statistics</code>: The most useful statistic is <code>Sum</code>.</p>\n               <p>\n                  <code>Unit</code>: The published unit is <code>None</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>TotalErrorRate</code>\n                  </b> - The percentage of all\n          viewer requests for which the response's HTTP status code was 4xx or 5xx.</p>\n               <p>\n                  <code>Statistics</code>: The most useful statistic is <code>Average</code>.</p>\n               <p>\n                  <code>Unit</code>: The published unit is <code>Percent</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>4xxErrorRate</code>\n                  </b> - The percentage of all\n          viewer requests for which the response's HTTP status cod was 4xx. In these cases, the\n          client or client viewer may have made an error. For example, a status code of 404 (Not\n          Found) means that the client requested an object that could not be found.</p>\n               <p>\n                  <code>Statistics</code>: The most useful statistic is <code>Average</code>.</p>\n               <p>\n                  <code>Unit</code>: The published unit is <code>Percent</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>5xxErrorRate</code>\n                  </b> - The percentage of all\n          viewer requests for which the response's HTTP status code was 5xx. In these cases, the\n          origin server did not satisfy the requests. For example, a status code of 503 (Service\n          Unavailable) means that the origin server is currently unavailable.</p>\n               <p>\n                  <code>Statistics</code>: The most useful statistic is <code>Average</code>.</p>\n               <p>\n                  <code>Unit</code>: The published unit is <code>Percent</code>.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    GetDistributionMetricDataRequest.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'startTime', traits: {"smithy.api#documentation" => "<p>The start of the time interval for which to get metric data.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Specified in Coordinated Universal Time (UTC).</p>\n            </li>\n            <li>\n               <p>Specified in the Unix time format.</p>\n               <p>For example, if you wish to use a start time of October 1, 2018, at 8 PM UTC, specify\n            <code>1538424000</code> as the start time.</p>\n            </li>\n         </ul>\n         <p>You can convert a human-friendly time to Unix time format using a converter like <a href=\"https://www.epochconverter.com/\">Epoch converter</a>.</p>", "smithy.api#required" => {}}))
    GetDistributionMetricDataRequest.add_member(:end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'endTime', traits: {"smithy.api#documentation" => "<p>The end of the time interval for which to get metric data.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Specified in Coordinated Universal Time (UTC).</p>\n            </li>\n            <li>\n               <p>Specified in the Unix time format.</p>\n               <p>For example, if you wish to use an end time of October 1, 2018, at 9 PM UTC, specify\n            <code>1538427600</code> as the end time.</p>\n            </li>\n         </ul>\n         <p>You can convert a human-friendly time to Unix time format using a converter like <a href=\"https://www.epochconverter.com/\">Epoch converter</a>.</p>", "smithy.api#required" => {}}))
    GetDistributionMetricDataRequest.add_member(:period, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricPeriod, location_name: 'period', traits: {"smithy.api#documentation" => "<p>The granularity, in seconds, for the metric data points that will be returned.</p>", "smithy.api#required" => {}}))
    GetDistributionMetricDataRequest.add_member(:unit, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricUnit, location_name: 'unit', traits: {"smithy.api#documentation" => "<p>The unit for the metric data request.</p>\n         <p>Valid units depend on the metric data being requested. For the valid units with each\n      available metric, see the <code>metricName</code> parameter.</p>", "smithy.api#required" => {}}))
    GetDistributionMetricDataRequest.add_member(:statistics, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricStatisticList, location_name: 'statistics', traits: {"smithy.api#documentation" => "<p>The statistic for the metric.</p>\n         <p>The following statistics are available:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>Minimum</code> - The lowest value observed during the specified period. Use this\n          value to determine low volumes of activity for your application.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Maximum</code> - The highest value observed during the specified period. Use\n          this value to determine high volumes of activity for your application.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Sum</code> - All values submitted for the matching metric added together. You\n          can use this statistic to determine the total volume of a metric.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Average</code> - The value of Sum / SampleCount during the specified period. By\n          comparing this statistic with the Minimum and Maximum values, you can determine the full\n          scope of a metric and how close the average use is to the Minimum and Maximum values. This\n          comparison helps you to know when to increase or decrease your resources.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SampleCount</code> - The count, or number, of data points used for the\n          statistical calculation.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    GetDistributionMetricDataRequest.type = Types::GetDistributionMetricDataRequest
    GetDistributionMetricDataResult.add_member(:metric_name, Smithy::Schema::Shapes::ShapeRef.new(shape: DistributionMetricName, location_name: 'metricName', traits: {"smithy.api#documentation" => "<p>The name of the metric returned.</p>"}))
