    GetInstanceSnapshotsResult.add_member(:next_page_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'nextPageToken', traits: {"smithy.api#documentation" => "<p>The token to advance to the next page of results from your request.</p>\n         <p>A next page token is not returned if there are no more results to display.</p>\n         <p>To get the next page of results, perform another <code>GetInstanceSnapshots</code> request\n      and specify the next page token using the <code>pageToken</code> parameter.</p>"}))
