    GetRelationalDatabaseLogEventsRequest.add_member(:log_stream_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'logStreamName', traits: {"smithy.api#documentation" => "<p>The name of the log stream.</p>\n         <p>Use the <code>get relational database log streams</code> operation to get a list of\n      available log streams.</p>", "smithy.api#required" => {}}))
    GetRelationalDatabaseLogEventsRequest.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: IsoDate, location_name: 'startTime', traits: {"smithy.api#documentation" => "<p>The start of the time interval from which to get log events.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Specified in Coordinated Universal Time (UTC).</p>\n            </li>\n            <li>\n               <p>Specified in the Unix time format.</p>\n               <p>For example, if you wish to use a start time of October 1, 2018, at 8 PM UTC, then you\n          input <code>1538424000</code> as the start time.</p>\n            </li>\n         </ul>"}))
