    GetRelationalDatabaseLogEventsRequest.add_member(:start_from_head, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'startFromHead', traits: {"smithy.api#documentation" => "<p>Parameter to specify if the log should start from head or tail. If <code>true</code> is\n      specified, the log event starts from the head of the log. If <code>false</code> is specified,\n      the log event starts from the tail of the log.</p>\n         <note>\n            <p>For PostgreSQL, the default value of <code>false</code> is the only option\n        available.</p>\n         </note>"}))
