    HostKeyAttributes.add_member(:fingerprint_sha1, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'fingerprintSHA1', traits: {"smithy.api#documentation" => "<p>The SHA-1 fingerprint of the returned SSH host key or RDP certificate.</p>\n         <ul>\n            <li>\n               <p>Example of an SHA-1 SSH fingerprint:</p>\n               <p>\n                  <code>SHA1:1CHH6FaAaXjtFOsR/t83vf91SR0</code>\n               </p>\n            </li>\n            <li>\n               <p>Example of an SHA-1 RDP fingerprint:</p>\n               <p>\n                  <code>af:34:51:fe:09:f0:e0:da:b8:4e:56:ca:60:c2:10:ff:38:06:db:45</code>\n               </p>\n            </li>\n         </ul>"}))
