    InstanceMetadataOptions.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMetadataState, location_name: 'state', traits: {"smithy.api#documentation" => "<p>The state of the metadata option changes.</p>\n         <p>The following states are possible:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>pending</code> - The metadata options are being updated. The instance is not yet\n          ready to process metadata traffic with the new selection.</p>\n            </li>\n            <li>\n               <p>\n                  <code>applied</code> - The metadata options have been successfully applied to the\n          instance.</p>\n            </li>\n         </ul>"}))
    InstanceMetadataOptions.add_member(:http_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: HttpTokens, location_name: 'httpTokens', traits: {"smithy.api#documentation" => "<p>The state of token usage for your instance metadata requests.</p>\n         <p>If the state is <code>optional</code>, you can choose whether to retrieve instance\n      metadata with a signed token header on your request. If you retrieve the IAM role credentials\n      without a token, the version 1.0 role credentials are returned. If you retrieve the IAM role\n      credentials by using a valid signed token, the version 2.0 role credentials are\n      returned.</p>\n         <p>If the state is <code>required</code>, you must send a signed token header with all\n      instance metadata retrieval requests. In this state, retrieving the IAM role credential always\n      returns the version 2.0 credentials. The version 1.0 credentials are not available.</p>\n         <important>\n            <p>Not all instance blueprints in Lightsail support version 2.0 credentials.\n        Use the <code>MetadataNoToken</code> instance metric to track the number of calls to the\n        instance metadata service that are using version 1.0 credentials. For more information, see\n          <a href=\"https://docs.aws.amazon.com/lightsail/latest/userguide/amazon-lightsail-viewing-instance-health-metrics\">Viewing instance metrics in Amazon Lightsail</a> in the <i>Amazon Lightsail Developer Guide</i>.</p>\n         </important>"}))
    InstanceMetadataOptions.add_member(:http_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: HttpEndpoint, location_name: 'httpEndpoint', traits: {"smithy.api#documentation" => "<p>Indicates whether the HTTP metadata endpoint on your instances is enabled or\n      disabled.</p>\n         <p>If the value is <code>disabled</code>, you cannot access your instance metadata.</p>"}))
    InstanceMetadataOptions.add_member(:http_put_response_hop_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'httpPutResponseHopLimit', traits: {"smithy.api#documentation" => "<p>The desired HTTP PUT response hop limit for instance metadata requests. A larger number\n      means that the instance metadata requests can travel farther.</p>"}))
    InstanceMetadataOptions.add_member(:http_protocol_ipv6, Smithy::Schema::Shapes::ShapeRef.new(shape: HttpProtocolIpv6, location_name: 'httpProtocolIpv6', traits: {"smithy.api#documentation" => "<p>Indicates whether the IPv6 endpoint for the instance metadata service is enabled or\n      disabled.</p>"}))
    InstanceMetadataOptions.type = Types::InstanceMetadataOptions
    InstanceMetadataState.add_member(:pending, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'pending', traits: {"smithy.api#enumValue" => "pending"}))
