    InstanceMetricName.add_member(:cpu_utilization, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'CPUUtilization', traits: {"smithy.api#enumValue" => "CPUUtilization"}))
    InstanceMetricName.add_member(:network_in, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NetworkIn', traits: {"smithy.api#enumValue" => "NetworkIn"}))
    InstanceMetricName.add_member(:network_out, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NetworkOut', traits: {"smithy.api#enumValue" => "NetworkOut"}))
    InstanceMetricName.add_member(:status_check_failed, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'StatusCheckFailed', traits: {"smithy.api#enumValue" => "StatusCheckFailed"}))
    InstanceMetricName.add_member(:status_check_failed_instance, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'StatusCheckFailed_Instance', traits: {"smithy.api#enumValue" => "StatusCheckFailed_Instance"}))
    InstanceMetricName.add_member(:status_check_failed_system, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'StatusCheckFailed_System', traits: {"smithy.api#enumValue" => "StatusCheckFailed_System"}))
    InstanceMetricName.add_member(:burst_capacity_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'BurstCapacityTime', traits: {"smithy.api#enumValue" => "BurstCapacityTime"}))
    InstanceMetricName.add_member(:burst_capacity_percentage, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'BurstCapacityPercentage', traits: {"smithy.api#enumValue" => "BurstCapacityPercentage"}))
    InstanceMetricName.add_member(:metadata_no_token, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MetadataNoToken', traits: {"smithy.api#enumValue" => "MetadataNoToken"}))
    InstanceNetworking.add_member(:monthly_transfer, Smithy::Schema::Shapes::ShapeRef.new(shape: MonthlyTransfer, location_name: 'monthlyTransfer', traits: {"smithy.api#documentation" => "<p>The amount of data in GB allocated for monthly data transfers.</p>"}))
    InstanceNetworking.add_member(:ports, Smithy::Schema::Shapes::ShapeRef.new(shape: InstancePortInfoList, location_name: 'ports', traits: {"smithy.api#documentation" => "<p>An array of key-value pairs containing information about the ports on the instance.</p>"}))
    InstanceNetworking.type = Types::InstanceNetworking
    InstancePlatform.add_member(:linux_unix, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'LinuxUnix', traits: {"smithy.api#enumValue" => "LINUX_UNIX"}))
    InstancePlatform.add_member(:windows, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'Windows', traits: {"smithy.api#enumValue" => "WINDOWS"}))
    InstancePlatformList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: InstancePlatform)
    InstancePortInfo.add_member(:from_port, Smithy::Schema::Shapes::ShapeRef.new(shape: Port, location_name: 'fromPort', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The first port in a range of open ports on an instance.</p>\n         <p>Allowed ports:</p>\n         <ul>\n            <li>\n               <p>TCP and UDP - <code>0</code> to <code>65535</code>\n               </p>\n            </li>\n            <li>\n               <p>ICMP - The ICMP type for IPv4 addresses. For example, specify <code>8</code> as the\n            <code>fromPort</code> (ICMP type), and <code>-1</code> as the <code>toPort</code> (ICMP\n          code), to enable ICMP Ping. For more information, see <a href=\"https://en.wikipedia.org/wiki/Internet_Control_Message_Protocol#Control_messages\">Control Messages</a> on <i>Wikipedia</i>.</p>\n            </li>\n            <li>\n               <p>ICMPv6 - The ICMP type for IPv6 addresses. For example, specify <code>128</code> as\n          the <code>fromPort</code> (ICMPv6 type), and <code>0</code> as <code>toPort</code> (ICMPv6\n          code). For more information, see <a href=\"https://en.wikipedia.org/wiki/Internet_Control_Message_Protocol_for_IPv6\">Internet\n            Control Message Protocol for IPv6</a>.</p>\n            </li>\n         </ul>"}))
    InstancePortInfo.add_member(:to_port, Smithy::Schema::Shapes::ShapeRef.new(shape: Port, location_name: 'toPort', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The last port in a range of open ports on an instance.</p>\n         <p>Allowed ports:</p>\n         <ul>\n            <li>\n               <p>TCP and UDP - <code>0</code> to <code>65535</code>\n               </p>\n            </li>\n            <li>\n               <p>ICMP - The ICMP code for IPv4 addresses. For example, specify <code>8</code> as the\n            <code>fromPort</code> (ICMP type), and <code>-1</code> as the <code>toPort</code> (ICMP\n          code), to enable ICMP Ping. For more information, see <a href=\"https://en.wikipedia.org/wiki/Internet_Control_Message_Protocol#Control_messages\">Control Messages</a> on <i>Wikipedia</i>.</p>\n            </li>\n            <li>\n               <p>ICMPv6 - The ICMP code for IPv6 addresses. For example, specify <code>128</code> as\n          the <code>fromPort</code> (ICMPv6 type), and <code>0</code> as <code>toPort</code> (ICMPv6\n          code). For more information, see <a href=\"https://en.wikipedia.org/wiki/Internet_Control_Message_Protocol_for_IPv6\">Internet\n            Control Message Protocol for IPv6</a>.</p>\n            </li>\n         </ul>"}))
    InstancePortInfo.add_member(:protocol, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkProtocol, location_name: 'protocol', traits: {"smithy.api#documentation" => "<p>The IP protocol name.</p>\n         <p>The name can be one of the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>tcp</code> - Transmission Control Protocol (TCP) provides reliable, ordered, and\n          error-checked delivery of streamed data between applications running on hosts\n          communicating by an IP network. If you have an application that doesn't require reliable\n          data stream service, use UDP instead.</p>\n            </li>\n            <li>\n               <p>\n                  <code>all</code> - All transport layer protocol types. For more general information,\n          see <a href=\"https://en.wikipedia.org/wiki/Transport_layer\">Transport layer</a> on\n            <i>Wikipedia</i>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>udp</code> - With User Datagram Protocol (UDP), computer applications can send\n          messages (or datagrams) to other hosts on an Internet Protocol (IP) network. Prior\n          communications are not required to set up transmission channels or data paths.\n          Applications that don't require reliable data stream service can use UDP, which provides a\n          connectionless datagram service that emphasizes reduced latency over reliability. If you\n          do require reliable data stream service, use TCP instead.</p>\n            </li>\n            <li>\n               <p>\n                  <code>icmp</code> - Internet Control Message Protocol (ICMP) is used to send error\n          messages and operational information indicating success or failure when communicating with\n          an instance. For example, an error is indicated when an instance could not be reached.\n          When you specify <code>icmp</code> as the <code>protocol</code>, you must specify the ICMP\n          type using the <code>fromPort</code> parameter, and ICMP code using the\n            <code>toPort</code> parameter.</p>\n            </li>\n            <li>\n               <p>\n                  <code>icmp6</code> - Internet Control Message Protocol (ICMP) for IPv6. When you\n          specify <code>icmp6</code> as the <code>protocol</code>, you must specify the ICMP type\n          using the <code>fromPort</code> parameter, and ICMP code using the <code>toPort</code>\n          parameter.</p>\n            </li>\n         </ul>"}))
    InstancePortInfo.add_member(:access_from, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'accessFrom', traits: {"smithy.api#documentation" => "<p>The location from which access is allowed. For example, <code>Anywhere (0.0.0.0/0)</code>,\n      or <code>Custom</code> if a specific IP address or range of IP addresses is allowed.</p>"}))
    InstancePortInfo.add_member(:access_type, Smithy::Schema::Shapes::ShapeRef.new(shape: PortAccessType, location_name: 'accessType', traits: {"smithy.api#documentation" => "<p>The type of access (<code>Public</code> or <code>Private</code>).</p>"}))
    InstancePortInfo.add_member(:common_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'commonName', traits: {"smithy.api#documentation" => "<p>The common name of the port information.</p>"}))
    InstancePortInfo.add_member(:access_direction, Smithy::Schema::Shapes::ShapeRef.new(shape: AccessDirection, location_name: 'accessDirection', traits: {"smithy.api#documentation" => "<p>The access direction (<code>inbound</code> or <code>outbound</code>).</p>\n         <note>\n            <p>Lightsail currently supports only <code>inbound</code> access direction.</p>\n         </note>"}))
    InstancePortInfo.add_member(:cidrs, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'cidrs', traits: {"smithy.api#documentation" => "<p>The IPv4 address, or range of IPv4 addresses (in CIDR notation) that are allowed to\n      connect to an instance through the ports, and the protocol.</p>\n         <note>\n            <p>The <code>ipv6Cidrs</code> parameter lists the IPv6 addresses that are allowed to\n        connect to an instance.</p>\n         </note>\n         <p>For more information about CIDR block notation, see <a href=\"https://en.wikipedia.org/wiki/Classless_Inter-Domain_Routing#CIDR_notation\">Classless\n        Inter-Domain Routing</a> on <i>Wikipedia</i>.</p>"}))
    InstancePortInfo.add_member(:ipv6_cidrs, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'ipv6Cidrs', traits: {"smithy.api#documentation" => "<p>The IPv6 address, or range of IPv6 addresses (in CIDR notation) that are allowed to\n      connect to an instance through the ports, and the protocol. Only devices with an IPv6 address\n      can connect to an instance through IPv6; otherwise, IPv4 should be used.</p>\n         <note>\n            <p>The <code>cidrs</code> parameter lists the IPv4 addresses that are allowed to connect to\n        an instance.</p>\n         </note>\n         <p>For more information about CIDR block notation, see <a href=\"https://en.wikipedia.org/wiki/Classless_Inter-Domain_Routing#CIDR_notation\">Classless\n        Inter-Domain Routing</a> on <i>Wikipedia</i>.</p>"}))
    InstancePortInfo.add_member(:cidr_list_aliases, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'cidrListAliases', traits: {"smithy.api#documentation" => "<p>An alias that defines access for a preconfigured range of IP addresses.</p>\n         <p>The only alias currently supported is <code>lightsail-connect</code>, which allows IP\n      addresses of the browser-based RDP/SSH client in the Lightsail console to connect to your\n      instance.</p>"}))
