    InstanceSnapshot.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceName, location_name: 'name', traits: {"smithy.api#documentation" => "<p>The name of the snapshot.</p>"}))
    InstanceSnapshot.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'arn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the snapshot\n        (<code>arn:aws:lightsail:us-east-2:123456789101:InstanceSnapshot/d23b5706-3322-4d83-81e5-12345EXAMPLE</code>).</p>"}))
    InstanceSnapshot.add_member(:support_code, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'supportCode', traits: {"smithy.api#documentation" => "<p>The support code. Include this code in your email to support when you have questions about\n      an instance or another resource in Lightsail. This code enables our support team to look up\n      your Lightsail information more easily.</p>"}))
    InstanceSnapshot.add_member(:created_at, Smithy::Schema::Shapes::ShapeRef.new(shape: IsoDate, location_name: 'createdAt', traits: {"smithy.api#documentation" => "<p>The timestamp when the snapshot was created (<code>1479907467.024</code>).</p>"}))
    InstanceSnapshot.add_member(:location, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceLocation, location_name: 'location', traits: {"smithy.api#documentation" => "<p>The region name and Availability Zone where you created the snapshot.</p>"}))
