    InstanceSnapshot.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>The tag keys and optional values for the resource. For more information about tags in\n      Lightsail, see the <a href=\"https://docs.aws.amazon.com/lightsail/latest/userguide/amazon-lightsail-tags\">Amazon Lightsail Developer Guide</a>.</p>"}))
    InstanceSnapshot.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceSnapshotState, location_name: 'state', traits: {"smithy.api#documentation" => "<p>The state the snapshot is in.</p>"}))
