    InstanceSnapshot.add_member(:from_attached_disks, Smithy::Schema::Shapes::ShapeRef.new(shape: DiskList, location_name: 'fromAttachedDisks', traits: {"smithy.api#documentation" => "<p>An array of disk objects containing information about all block storage disks.</p>"}))
    InstanceSnapshot.add_member(:from_instance_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceName, location_name: 'fromInstanceName', traits: {"smithy.api#documentation" => "<p>The instance from which the snapshot was created.</p>"}))
    InstanceSnapshot.add_member(:from_instance_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'fromInstanceArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the instance from which the snapshot was created\n        (<code>arn:aws:lightsail:us-east-2:123456789101:Instance/64b8404c-ccb1-430b-8daf-12345EXAMPLE</code>).</p>"}))
    InstanceSnapshot.add_member(:from_blueprint_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'fromBlueprintId', traits: {"smithy.api#documentation" => "<p>The blueprint ID from which you created the snapshot (<code>amazon_linux_2023</code>). A\n      blueprint is a virtual private server (or <i>instance</i>) image used to create\n      instances quickly.</p>"}))
