    LoadBalancerTlsCertificate.add_member(:resource_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceType, location_name: 'resourceType', traits: {"smithy.api#documentation" => "<p>The resource type (<code>LoadBalancerTlsCertificate</code>).</p>\n         <ul>\n            <li>\n               <p>\n                  <b>\n                     <code>Instance</code>\n                  </b> - A Lightsail instance (a\n          virtual private server)</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>StaticIp</code>\n                  </b> - A static IP address</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>KeyPair</code>\n                  </b> - The key pair used to connect\n          to a Lightsail instance</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>InstanceSnapshot</code>\n                  </b> - A Lightsail\n          instance snapshot</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>Domain</code>\n                  </b> - A DNS zone</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>PeeredVpc</code>\n                  </b> - A peered VPC</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>LoadBalancer</code>\n                  </b> - A Lightsail load\n          balancer</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>LoadBalancerTlsCertificate</code>\n                  </b> - An SSL/TLS\n          certificate associated with a Lightsail load balancer</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>Disk</code>\n                  </b> - A Lightsail block storage\n          disk</p>\n            </li>\n            <li>\n               <p>\n                  <b>\n                     <code>DiskSnapshot</code>\n                  </b> - A block storage disk\n          snapshot</p>\n            </li>\n         </ul>"}))
