    PrivateRegistryAccess.add_member(:ecr_image_puller_role, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerServiceECRImagePullerRole, location_name: 'ecrImagePullerRole', traits: {"smithy.api#documentation" => "<p>An object that describes the activation status of the role that you can use to grant a\n        Lightsail container service access to Amazon ECR private\n      repositories. If the role is activated, the Amazon Resource Name (ARN) of the role is also\n      listed.</p>"}))
