    QueryStringObject.add_member(:query_strings_allow_list, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'queryStringsAllowList', traits: {"smithy.api#documentation" => "<p>The specific query strings that the distribution forwards to the origin.</p>\n         <p>Your distribution will cache content based on the specified query strings.</p>\n         <p>If the <code>option</code> parameter is true, then your distribution forwards all query\n      strings, regardless of what you specify using the <code>queryStringsAllowList</code>\n      parameter.</p>"}))
