    UpdateDistributionRequest.add_member(:is_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'isEnabled', traits: {"smithy.api#documentation" => "<p>Indicates whether to enable the distribution.</p>"}))
    UpdateDistributionRequest.add_member(:viewer_minimum_tls_protocol_version, Smithy::Schema::Shapes::ShapeRef.new(shape: ViewerMinimumTlsProtocolVersionEnum, location_name: 'viewerMinimumTlsProtocolVersion', traits: {"smithy.api#documentation" => "<p>Use this parameter to update the minimum TLS protocol version for the SSL/TLS certificate\n      that's attached to the distribution.</p>"}))
    UpdateDistributionRequest.add_member(:certificate_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceName, location_name: 'certificateName', traits: {"smithy.api#documentation" => "<p>The name of the SSL/TLS certificate that you want to attach to the distribution.</p>\n         <p>Only certificates with a status of <code>ISSUED</code> can be attached to a\n      distribution.</p>\n         <p>Use the <a href=\"https://docs.aws.amazon.com/lightsail/2016-11-28/api-reference/API_GetCertificates.html\">GetCertificates</a>\n      action to get a list of certificate names that you can specify.</p>"}))
