    UpdateInstanceMetadataOptionsRequest.add_member(:instance_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceName, location_name: 'instanceName', traits: {"smithy.api#documentation" => "<p>The name of the instance for which to update metadata parameters.</p>", "smithy.api#required" => {}}))
    UpdateInstanceMetadataOptionsRequest.add_member(:http_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: HttpTokens, location_name: 'httpTokens', traits: {"smithy.api#documentation" => "<p>The state of token usage for your instance metadata requests. If the parameter is not\n      specified in the request, the default state is <code>optional</code>.</p>\n         <p>If the state is <code>optional</code>, you can choose whether to retrieve instance\n      metadata with a signed token header on your request. If you retrieve the IAM role credentials\n      without a token, the version 1.0 role credentials are returned. If you retrieve the IAM role\n      credentials by using a valid signed token, the version 2.0 role credentials are\n      returned.</p>\n         <p>If the state is <code>required</code>, you must send a signed token header with all\n      instance metadata retrieval requests. In this state, retrieving the IAM role credential always\n      returns the version 2.0 credentials. The version 1.0 credentials are not available.</p>"}))
    UpdateInstanceMetadataOptionsRequest.add_member(:http_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: HttpEndpoint, location_name: 'httpEndpoint', traits: {"smithy.api#documentation" => "<p>Enables or disables the HTTP metadata endpoint on your instances. If this parameter is not\n      specified, the existing state is maintained.</p>\n         <p>If you specify a value of <code>disabled</code>, you cannot access your instance\n      metadata.</p>"}))
    UpdateInstanceMetadataOptionsRequest.add_member(:http_put_response_hop_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'httpPutResponseHopLimit', traits: {"smithy.api#documentation" => "<p>The desired HTTP PUT response hop limit for instance metadata requests. A larger number\n      means that the instance metadata requests can travel farther. If no parameter is specified,\n      the existing state is maintained.</p>"}))
    UpdateInstanceMetadataOptionsRequest.add_member(:http_protocol_ipv6, Smithy::Schema::Shapes::ShapeRef.new(shape: HttpProtocolIpv6, location_name: 'httpProtocolIpv6', traits: {"smithy.api#documentation" => "<p>Enables or disables the IPv6 endpoint for the instance metadata service. This setting\n      applies only when the HTTP metadata endpoint is enabled.</p>\n         <note>\n            <p>This parameter is available only for instances in the Europe (Stockholm) Amazon Web Services Region (<code>eu-north-1</code>).</p>\n         </note>"}))
