    UpdateRelationalDatabaseRequest.add_member(:master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: SensitiveString, location_name: 'masterUserPassword', traits: {"smithy.api#documentation" => "<p>The password for the master user. The password can include any printable ASCII character\n      except \"/\", \"\"\", or \"@\".</p>\n         <p>My<b>SQL</b>\n         </p>\n         <p>Constraints: Must contain from 8 to 41 characters.</p>\n         <p>\n            <b>PostgreSQL</b>\n         </p>\n         <p>Constraints: Must contain from 8 to 128 characters.</p>"}))
    UpdateRelationalDatabaseRequest.add_member(:rotate_master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'rotateMasterUserPassword', traits: {"smithy.api#documentation" => "<p>When <code>true</code>, the master user password is changed to a new strong password\n      generated by Lightsail.</p>\n         <p>Use the <code>get relational database master user password</code> operation to get the new\n      password.</p>"}))
    UpdateRelationalDatabaseRequest.add_member(:preferred_backup_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'preferredBackupWindow', traits: {"smithy.api#documentation" => "<p>The daily time range during which automated backups are created for your database if\n      automated backups are enabled.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the <code>hh24:mi-hh24:mi</code> format.</p>\n               <p>Example: <code>16:00-16:30</code>\n               </p>\n            </li>\n            <li>\n               <p>Specified in Coordinated Universal Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must not conflict with the preferred maintenance window.</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    UpdateRelationalDatabaseRequest.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'preferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The weekly time range during which system maintenance can occur on your database.</p>\n         <p>The default is a 30-minute window selected at random from an 8-hour block of time for each\n        Amazon Web Services Region, occurring on a random day of the week.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the <code>ddd:hh24:mi-ddd:hh24:mi</code> format.</p>\n            </li>\n            <li>\n               <p>Valid days: Mon, Tue, Wed, Thu, Fri, Sat, Sun.</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n            <li>\n               <p>Specified in Coordinated Universal Time (UTC).</p>\n            </li>\n            <li>\n               <p>Example: <code>Tue:17:00-Tue:17:30</code>\n               </p>\n            </li>\n         </ul>"}))
    UpdateRelationalDatabaseRequest.add_member(:enable_backup_retention, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'enableBackupRetention', traits: {"smithy.api#documentation" => "<p>When <code>true</code>, enables automated backup retention for your database.</p>\n         <p>Updates are applied during the next maintenance window because this can result in an\n      outage.</p>"}))
    UpdateRelationalDatabaseRequest.add_member(:disable_backup_retention, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'disableBackupRetention', traits: {"smithy.api#documentation" => "<p>When <code>true</code>, disables automated backup retention for your database.</p>\n         <p>Disabling backup retention deletes all automated database backups. Before disabling this,\n      you may want to create a snapshot of your database using the <code>create relational database\n        snapshot</code> operation.</p>\n         <p>Updates are applied during the next maintenance window because this can result in an\n      outage.</p>"}))
    UpdateRelationalDatabaseRequest.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'publiclyAccessible', traits: {"smithy.api#documentation" => "<p>Specifies the accessibility options for your database. A value of <code>true</code>\n      specifies a database that is available to resources outside of your Lightsail account. A\n      value of <code>false</code> specifies a database that is available only to your Lightsail\n      resources in the same region as your database.</p>"}))
    UpdateRelationalDatabaseRequest.add_member(:apply_immediately, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'applyImmediately', traits: {"smithy.api#documentation" => "<p>When <code>true</code>, applies changes immediately. When <code>false</code>, applies\n      changes during the preferred maintenance window. Some changes may cause an outage.</p>\n         <p>Default: <code>false</code>\n         </p>"}))
    UpdateRelationalDatabaseRequest.add_member(:ca_certificate_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'caCertificateIdentifier', traits: {"smithy.api#documentation" => "<p>Indicates the certificate that needs to be associated with the database.</p>"}))
    UpdateRelationalDatabaseRequest.add_member(:relational_database_blueprint_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'relationalDatabaseBlueprintId', traits: {"smithy.api#documentation" => "<p>This parameter is used to update the major version of the database. Enter the\n        <code>blueprintId</code> for the major version that you want to update to.</p>\n         <p>Use the <a href=\"https://docs.aws.amazon.com/lightsail/2016-11-28/api-reference/API_GetRelationalDatabaseBlueprints.html\">GetRelationalDatabaseBlueprints</a> action to get a list of available blueprint\n      IDs.</p>"}))
